`timescale 1ns / 1ps
// Repro for bucket B1 (data_byte_fail): the eight data bits must leave the
// transmitter least significant bit first. Only the data bits are checked.
module tb_uart_frame_tx;
    localparam integer C = 4;

    reg            clk      = 1'b0;
    reg            rst      = 1'b1;
    reg            start    = 1'b0;
    reg  [7:0]     data     = 8'd0;
    wire           tx;
    wire           busy;
    integer        checks   = 0;
    integer        failed   = 0;
    reg            reported = 1'b0;
    reg [8*64-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(C)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task finish_with_verdict;
        begin
            if (!reported) begin
                reported = 1'b1;
                $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failed);
                $finish;
            end
        end
    endtask

    // Called at a negedge; returns at the first negedge of the start bit.
    task send_frame(input [7:0] value);
        begin
            while (busy !== 1'b0) @(negedge clk);
            data  = value;
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;
        end
    endtask

    task check_data(input [7:0] value);
        integer i;
        begin
            send_frame(value);
            repeat (C / 2) @(negedge clk);            // middle of the start bit
            for (i = 0; i < 8; i = i + 1) begin
                repeat (C) @(negedge clk);            // middle of data bit i
                checks = checks + 1;
                if (tx !== value[i]) begin
                    failed = failed + 1;
                    $display("CHECK data_bit FAIL byte=%h bit=%0d expected=%b got=%b",
                             value, i, value[i], tx);
                end
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("NONCE=%s", nonce))
            if (!$value$plusargs("nonce=%s", nonce))
                nonce = "unset";
        repeat (3) @(negedge clk);
        rst = 1'b0;
        @(negedge clk);
        check_data(8'h01);
        check_data(8'h4D);
        check_data(8'h0F);
        check_data(8'hE6);
        while (busy !== 1'b0) @(negedge clk);
        finish_with_verdict;
    end

    initial begin
        #100000;
        failed = failed + 1;
        $display("CHECK watchdog FAIL simulation did not complete");
        finish_with_verdict;
    end
endmodule
=== END FILE ===
