// Repro for bucket B3 (frame_period_fail): a frame (start, 8 data, parity,
// stop) must keep busy high for exactly 11*CLKS_PER_BIT cycles, and tx must be
// high for the whole stop bit. Data and parity values are not checked.
module tb_uart_frame_tx;
    localparam integer C = 4;

    reg            clk      = 1'b0;
    reg            rst      = 1'b1;
    reg            start    = 1'b0;
    reg  [7:0]     data     = 8'd0;
    wire           tx;
    wire           busy;
    integer        checks   = 0;
    integer        failed   = 0;
    reg            reported = 1'b0;
    reg [8*64-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(C)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task finish_with_verdict;
        begin
            if (!reported) begin
                reported = 1'b1;
                $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failed);
                $finish;
            end
        end
    endtask

    // Called at a negedge; returns at the first negedge of the start bit.
    task send_frame(input [7:0] value);
        begin
            while (busy !== 1'b0) @(negedge clk);
            data  = value;
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;
        end
    endtask

    task check_frame(input [7:0] value);
        integer n;
        reg     stop_low;
        begin
            send_frame(value);
            n        = 0;
            stop_low = 1'b0;
            while (busy === 1'b1 && n < 20 * C) begin
                if (n >= 10 * C && tx !== 1'b1)
                    stop_low = 1'b1;
                n = n + 1;
                @(negedge clk);
            end
            checks = checks + 1;
            if (n != 11 * C) begin
                failed = failed + 1;
                $display("CHECK frame_length FAIL byte=%h expected_cycles=%0d got_cycles=%0d",
                         value, 11 * C, n);
            end
            checks = checks + 1;
            if (stop_low) begin
                failed = failed + 1;
                $display("CHECK stop_level FAIL byte=%h tx low during stop bit", value);
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("NONCE=%s", nonce))
            if (!$value$plusargs("nonce=%s", nonce))
                nonce = "unset";
        repeat (3) @(negedge clk);
        rst = 1'b0;
        @(negedge clk);
        check_frame(8'h55);
        check_frame(8'h00);
        check_frame(8'hFF);
        while (busy !== 1'b0) @(negedge clk);
        finish_with_verdict;
    end

    initial begin
        #100000;
        failed = failed + 1;
        $display("CHECK watchdog FAIL simulation did not complete");
        finish_with_verdict;
    end
endmodule
